import java.util.*;

public class E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        sc.close();
        int l = s.length();
        if (l < 2) {
            System.out.println(countShort(s, l));
        } else {
            System.out.println(countLong(s, l));
        }
        System.exit(0);
    }

    static int countShort(String s, int l) {
        if (l == 1) return (s.equals("0") || s.equals("_") || s.equals("X")) ? 1 : 0;
        // l == 2
        int count = 0;
        for (int i = 10; i <= 95; i += 5) {
            if (i % 25 != 0) continue;
            String str = Integer.toString(i);
            count += matchTwo(s, str) ? 1 : 0;
        }
        return count;
    }

    static boolean matchTwo(String pattern, String candidate) {
        char p0 = pattern.charAt(0), p1 = pattern.charAt(1);
        char c0 = candidate.charAt(0), c1 = candidate.charAt(1);
        if (p0 >= '0' && p0 <= '9' && p1 >= '0' && p1 <= '9')
            return pattern.equals(candidate);
        if (p0 >= '0' && p0 <= '9')
            return p0 == c0;
        if (p0 == '_') {
            if (p1 >= '0' && p1 <= '9')
                return p1 == c1;
            return true;
        }
        if (p1 >= '0' && p1 <= '9')
            return p1 == c1;
        return p1 == '_';
    }

    static int countLong(String s, int l) {
        int start = (int) Math.pow(10, l - 1);
        int end = (int) Math.pow(10, l);
        int count = 0;
        for (int i = start; i < end; i += 25) {
            String str = Integer.toString(i);
            if (matchesLong(s, str)) count++;
        }
        return count;
    }

    static boolean matchesLong(String pattern, String candidate) {
        Set<Character> set = new HashSet<>();
        for (int j = 0; j < pattern.length(); j++) {
            char p = pattern.charAt(j);
            if (p == '_') continue;
            if (p == 'X') set.add(candidate.charAt(j));
            else if (p != candidate.charAt(j)) return false;
        }
        return set.size() < 2;
    }
}
